import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

/**
 * Filters the bank to one potion's ingredients and lines them up in a single
 * column, using the core Bank Tags plugin's tag + layout API. Nothing is
 * moved server-side: the layout is purely how the client draws the bank.
 */
@Slf4j
@PluginDescriptor(
	name = "Potion Prep",
	description = "Filter the bank to a potion's ingredients and see what you need to clean, crush or gather",
	tags = {"herblore", "herb", "herbs", "potion", "potions", "pots", "bank", "banktags", "layout", "tab", "unf", "unfinished", "secondary", "secondaries", "grimy", "clean", "crush", "prayer", "stamina", "brew", "antifire", "antivenom", "combat", "skilling", "planner", "calculator", "ironman"}
)
@PluginDependency(BankTagsPlugin.class)
public class PotionPrepPlugin extends Plugin
{
	static final String TAG = "potion prep";
	private static final int BANK_COLUMNS = 8;

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ClientToolbar clientToolbar;
	@Inject private ConfigManager configManager;
	@Inject private ItemManager itemManager;
	@Inject private PotionPrepConfig config;
	@Inject private TagManager tagManager;
	@Inject private LayoutManager layoutManager;
	@Inject private BankTagsService bankTagsService;

	private PotionPrepPanel panel;
	private NavigationButton navButton;

	private Potion selected;
	private final Set<Integer> trackedIds = new HashSet<>();

	// Last observed bank. Null means "not seen this session", which is different from empty.
	private Map<Integer, Integer> bankCounts;
	private long bankObservedAt;
	// Potion storage, read directly (see PotionStorageReader). Keyed by
	// 1-dose item id. Kept after the bank closes, like the bank snapshot.
	private Map<Integer, Integer> storageCounts = new HashMap<>();
	private boolean readStorage;
	private Set<Integer> storageVarps;
	// Dose rows collapsed to one slot because that potion is only in storage.
	private Set<Integer> collapsed = new HashSet<>();

	// The filter only applies while the panel is open and the toggle is on.
	private volatile boolean panelOpen;
	// Our tab has been shown during this bank visit, so a later bank build
	// without it means the player clicked away.
	private boolean shownThisVisit;
	private final Map<Integer, Integer> invCounts = new HashMap<>();
	private int herbloreLevel;   // real
	private int boostedLevel;
	// Whether the current layout includes the botanical pie row.
	private boolean layoutHasPie;
	private final Set<Integer> wornIds = new HashSet<>();
	/** Real item ids that have a bank placeholder. */
	private final Set<Integer> bankPlaceholders = new HashSet<>();
	private List<int[]> gearRows = new ArrayList<>();

	@Provides
	PotionPrepConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PotionPrepConfig.class);
	}

	@Override
	protected void startUp()
	{
		tagManager.registerTag(TAG, itemId -> trackedIds.contains(itemId));

		panel = new PotionPrepPanel(this, itemManager);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Potion Prep")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		Potion saved = parse(config.potion());
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				herbloreLevel = client.getRealSkillLevel(Skill.HERBLORE);
				boostedLevel = client.getBoostedSkillLevel(Skill.HERBLORE);
				readInventory(client.getItemContainer(InventoryID.INV));
				readBank(client.getItemContainer(InventoryID.BANK));
			}
			select(saved != null ? saved : Potion.PRAYER, false);
		});
	}

	@Override
	protected void shutDown()
	{
		clientThread.invokeLater(() ->
		{
			if (TAG.equals(bankTagsService.getActiveTag()))
			{
				bankTagsService.closeBankTag();
			}
			tagManager.unregisterTag(TAG);
			layoutManager.removeLayout(TAG);
		});
		clientToolbar.removeNavigation(navButton);
		panel = null;
		selected = null;
		bankCounts = null;
		storageCounts = new HashMap<>();
		collapsed = new HashSet<>();
		invCounts.clear();
	}

	// --- Called from the panel (EDT) ---

	void selectFromPanel(Potion potion)
	{
		clientThread.invokeLater(() -> select(potion, true));
	}

	/**
	 * The panel's "Show in bank" toggle. While on, every bank opened shows
	 * the selected potion's layout; turning it off restores the normal bank.
	 */
	void setShowInBank(boolean on)
	{
		configManager.setConfiguration(PotionPrepConfig.GROUP, "showInBank", on);
		clientThread.invokeLater(() ->
		{
			applyFilter();
			pushToPanel(null);
		});
	}

	/** The panel was shown or hidden in the sidebar. */
	void setPanelOpen(boolean open)
	{
		panelOpen = open;
		clientThread.invokeLater(this::applyFilter);
	}

	// --- Client thread ---

	private boolean pieNeeded()
	{
		return selected != null && PotionPlan.needsPie(selected, herbloreLevel, boostedLevel);
	}

	private boolean shouldFilter()
	{
		return config.showInBank() && panelOpen && selected != null;
	}

	/** Open or close our tab to match {@link #shouldFilter()}, if the bank is open. */
	private void applyFilter()
	{
		if (!isBankOpen())
		{
			return;
		}
		if (shouldFilter())
		{
			openTag();
		}
		else
		{
			closeOurTag();
		}
	}

	private void closeOurTag()
	{
		if (TAG.equals(bankTagsService.getActiveTag()))
		{
			// We are closing it, so the next bank build must not read as
			// "the player clicked away".
			shownThisVisit = false;
			bankTagsService.closeBankTag();
		}
	}

	private void select(Potion potion, boolean persist)
	{
		selected = potion;
		trackedIds.clear();
		trackedIds.addAll(PotionPlan.layoutItems(potion));
		layoutHasPie = pieNeeded();
		if (layoutHasPie)
		{
			Arrays.stream(PotionPlan.PIE_IDS).forEach(trackedIds::add);
		}
		if (persist)
		{
			configManager.setConfiguration(PotionPrepConfig.GROUP, "potion", potion.name());
		}
		collapsed = computeCollapsed();
		gearRows = gearRows();
		trackGear();
		saveLayout();
		if (TAG.equals(bankTagsService.getActiveTag()) && isBankOpen())
		{
			openTag();
		}
		pushToPanel(null);
	}

	private List<int[]> gearRows()
	{
		return Gear.rows(
			id -> bankCounts != null && bankCounts.getOrDefault(id, 0) > 0,
			id -> wornIds.contains(id) || invCounts.containsKey(id) || bankPlaceholders.contains(id));
	}

	private void trackGear()
	{
		for (int[] row : gearRows)
		{
			for (int id : row)
			{
				if (id != -1)
				{
					trackedIds.add(id);
				}
			}
		}
	}

	/** Recompute which gear to show; re-save and reopen the layout if it changed. */
	private void refreshGear()
	{
		if (selected == null)
		{
			return;
		}
		List<int[]> now = gearRows();
		if (sameRows(now, gearRows))
		{
			return;
		}
		gearRows = now;
		trackedIds.removeAll(Gear.allIds());
		trackGear();
		saveLayout();
		if (TAG.equals(bankTagsService.getActiveTag()) && isBankOpen())
		{
			openTag();
		}
	}

	private static boolean sameRows(List<int[]> a, List<int[]> b)
	{
		if (a.size() != b.size())
		{
			return false;
		}
		for (int i = 0; i < a.size(); i++)
		{
			if (!Arrays.equals(a.get(i), b.get(i)))
			{
				return false;
			}
		}
		return true;
	}

	private void saveLayout()
	{
		if (selected == null)
		{
			return;
		}
		int col = Math.max(1, Math.min(BANK_COLUMNS, config.column())) - 1;
		List<int[]> rows = new ArrayList<>(PotionPlan.layoutRows(selected));
		if (layoutHasPie)
		{
			// Eating the pie is the first task.
			rows.add(0, PotionPlan.PIE_IDS);
		}
		Layout layout = new Layout(TAG);
		List<boolean[]> occupied = new ArrayList<>();
		for (int row = 0; row < rows.size(); row++)
		{
			int[] ids = collapse(rows.get(row));
			// Each action row ends at the chosen column and runs leftwards,
			// or rightwards when there isn't room on the left.
			int start = Math.max(0, Math.min(col - (ids.length - 1), BANK_COLUMNS - ids.length));
			boolean[] used = new boolean[BANK_COLUMNS];
			for (int i = 0; i < ids.length; i++)
			{
				layout.setItemAtPos(ids[i], row * BANK_COLUMNS + start + i);
				used[start + i] = true;
			}
			occupied.add(used);
		}
		// Herblore gear sits on the left like the equipment tab, below any
		// rows too wide to leave room for it.
		int g = Gear.startRow(occupied, gearRows);
		for (int r = 0; r < gearRows.size(); r++)
		{
			for (int c = 0; c < Gear.WIDTH; c++)
			{
				int id = gearRows.get(r)[c];
				if (id != -1)
				{
					layout.setItemAtPos(id, (g + r) * BANK_COLUMNS + c);
				}
			}
		}
		layoutManager.saveLayout(layout);
	}

	/**
	 * Bank Tags matches every dose slot of a potion that is only in potion
	 * storage to the same stored potion, so (1)-(4) would show four copies.
	 * For those potions keep just the 4-dose slot.
	 */
	private int[] collapse(int[] ids)
	{
		if (collapsed.isEmpty())
		{
			return ids;
		}
		return Arrays.stream(ids).filter(id -> !collapsed.contains(id)).toArray();
	}

	/** 1-3 dose ids of potions in this layout that are in storage but not the bank. */
	private Set<Integer> computeCollapsed()
	{
		Set<Integer> out = new HashSet<>();
		if (selected == null)
		{
			return out;
		}
		for (Node n : PotionPlan.ingredients(selected))
		{
			if (!n.isDosed() || storageCounts.getOrDefault(n.getDoseIds()[0], 0) <= 0)
			{
				continue;
			}
			boolean inBank = false;
			for (int id : n.getDoseIds())
			{
				inBank |= bankCounts != null && bankCounts.containsKey(id);
			}
			if (!inBank)
			{
				for (int d = 0; d < 3; d++)
				{
					out.add(n.getDoseIds()[d]);
				}
			}
		}
		return out;
	}

	/** Recompute storage-only collapsing; re-save and reopen the layout if it changed. */
	private void refreshCollapsed()
	{
		Set<Integer> now = computeCollapsed();
		if (!now.equals(collapsed))
		{
			collapsed = now;
			saveLayout();
			if (TAG.equals(bankTagsService.getActiveTag()) && isBankOpen())
			{
				openTag();
			}
		}
	}

	private void openTag()
	{
		// No OPTION_ALLOW_MODIFICATIONS: dragging items in this view must not
		// rewrite the layout we generate.
		bankTagsService.openBankTag(TAG, 0);
	}

	private boolean isBankOpen()
	{
		Widget w = client.getWidget(InterfaceID.Bankmain.ITEMS);
		return w != null && !w.isHidden();
	}

	// Runs after Bank Tags (priority -1), the same hook Inventory Setups uses.
	@Subscribe(priority = -1)
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != ScriptID.BANKMAIN_INIT)
		{
			return;
		}
		shownThisVisit = false;
		if (shouldFilter())
		{
			openTag();
		}
		else if (TAG.equals(bankTagsService.getActiveTag()))
		{
			// Bank Tags remembers the last tab; don't come back to ours
			// unless the filter is on.
			bankTagsService.closeBankTag();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ScriptID.BANKMAIN_FINISHBUILDING)
		{
			return;
		}
		readStorage = true;

		boolean ours = TAG.equals(bankTagsService.getActiveTag());
		if (ours)
		{
			shownThisVisit = true;
		}
		else if (shownThisVisit && config.showInBank())
		{
			// The player clicked another tab (or Bank Tags' close) while our
			// view was up: treat that as turning the filter off.
			shownThisVisit = false;
			configManager.setConfiguration(PotionPrepConfig.GROUP, "showInBank", false);
			pushToPanel(null);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int varp = event.getVarpId();
		if (varp == VarPlayerID.POTIONSTORE_BASE_VAR_1 || varp == VarPlayerID.POTIONSTORE_BASE_VAR_2
			|| varp == VarPlayerID.POTIONSTORE_BASE_VAR_3 || varp == VarPlayerID.POTIONSTORE_BASE_VAR_4
			|| varp == VarPlayerID.POTIONSTORE_BASE_VAR_5 || varp == VarPlayerID.POTIONSTORE_BASE_VAR_6
			|| storageVarps != null && storageVarps.contains(varp))
		{
			readStorage = true;
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		// Scripts can't run from inside another script, so storage is read
		// here, on the tick after the bank builds or storage changes.
		if (!readStorage || !isBankOpen())
		{
			return;
		}
		readStorage = false;

		if (storageVarps == null)
		{
			Widget w = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_ITEMS);
			int[] trigger = w != null ? w.getVarTransmitTrigger() : null;
			if (trigger != null)
			{
				storageVarps = new HashSet<>();
				Arrays.stream(trigger).forEach(storageVarps::add);
			}
		}

		Map<Integer, Integer> now = PotionStorageReader.read(client);
		if (!now.equals(storageCounts))
		{
			storageCounts = now;
			refreshCollapsed();
			pushToPanel(null);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			shownThisVisit = false;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.BANK)
		{
			readBank(event.getItemContainer());
			refreshCollapsed();
			refreshGear();
			pushToPanel(null);
		}
		else if (event.getContainerId() == InventoryID.WORN)
		{
			wornIds.clear();
			wornIds.addAll(count(event.getItemContainer()).keySet());
			refreshGear();
		}
		else if (event.getContainerId() == InventoryID.INV)
		{
			readInventory(event.getItemContainer());
			refreshGear();
			pushToPanel(null);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() == Skill.HERBLORE
			&& (event.getLevel() != herbloreLevel || event.getBoostedLevel() != boostedLevel))
		{
			herbloreLevel = event.getLevel();
			boostedLevel = event.getBoostedLevel();
			// Eating a pie (or it wearing off) changes whether the pie row is needed.
			if (selected != null && pieNeeded() != layoutHasPie)
			{
				select(selected, false);
			}
			pushToPanel(null);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			if (event.getGameState() == GameState.LOGIN_SCREEN)
			{
				// Different account may log in next.
				bankCounts = null;
				storageCounts = new HashMap<>();
				collapsed = new HashSet<>();
				wornIds.clear();
				bankPlaceholders.clear();
				herbloreLevel = 0;
				boostedLevel = 0;
			}
			invCounts.clear();
			pushToPanel(null);
		}
		else if (event.getGameState() == GameState.LOGGED_IN && herbloreLevel == 0)
		{
			clientThread.invokeLater(() ->
			{
				herbloreLevel = client.getRealSkillLevel(Skill.HERBLORE);
				boostedLevel = client.getBoostedSkillLevel(Skill.HERBLORE);
				if (selected != null && pieNeeded() != layoutHasPie)
				{
					select(selected, false);
				}
				pushToPanel(null);
			});
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (PotionPrepConfig.GROUP.equals(event.getGroup()) && "column".equals(event.getKey()))
		{
			clientThread.invokeLater(() ->
			{
				saveLayout();
				if (TAG.equals(bankTagsService.getActiveTag()) && isBankOpen())
				{
					openTag();
				}
			});
		}
	}

	private void readBank(ItemContainer container)
	{
		if (container == null)
		{
			return;
		}
		bankCounts = count(container);
		bankPlaceholders.clear();
		for (Item item : container.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() == 0)
			{
				ItemComposition c = itemManager.getItemComposition(item.getId());
				if (c.getPlaceholderTemplateId() != -1)
				{
					bankPlaceholders.add(c.getPlaceholderId());
				}
			}
		}
		bankObservedAt = System.currentTimeMillis();
	}

	private void readInventory(ItemContainer container)
	{
		invCounts.clear();
		if (container != null)
		{
			invCounts.putAll(count(container));
		}
	}

	private static Map<Integer, Integer> count(ItemContainer container)
	{
		Map<Integer, Integer> out = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				out.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return out;
	}

	private Map<Integer, Integer> combinedCounts()
	{
		Map<Integer, Integer> all = new HashMap<>();
		if (bankCounts != null)
		{
			all.putAll(bankCounts);
		}
		storageCounts.forEach((id, qty) -> all.merge(id, qty, Integer::sum));
		invCounts.forEach((id, qty) -> all.merge(id, qty, Integer::sum));
		return all;
	}

	private void pushToPanel(String notice)
	{
		if (panel == null || selected == null)
		{
			return;
		}
		Map<Integer, Integer> counts = combinedCounts();
		int boosted = boostedLevel > 0 ? boostedLevel : herbloreLevel;
		PotionPlan plan = PotionPlan.compute(selected, counts,
			PotionPlan.effectiveLevel(selected, herbloreLevel, boosted), PotionPlan.needsPie(selected, herbloreLevel, boosted));
		Map<Potion, Integer> makeable = new EnumMap<>(Potion.class);
		Map<Potion, Double> xp = new EnumMap<>(Potion.class);
		Set<Potion> pie = EnumSet.noneOf(Potion.class);
		for (Potion p : Potion.values())
		{
			int eff = PotionPlan.effectiveLevel(p, herbloreLevel, boosted);
			makeable.put(p, PotionPlan.makeable(p, counts, eff));
			xp.put(p, PotionPlan.xp(p, counts, eff));
			if (PotionPlan.needsPie(p, herbloreLevel, boosted))
			{
				pie.add(p);
			}
		}
		int lvl = boosted;
		String status = notice != null ? notice
			: bankCounts == null ? "Open your bank to scan it"
			: "Bank seen " + ago(bankObservedAt);
		PotionPrepPanel p = panel;
		boolean showing = config.showInBank();
		SwingUtilities.invokeLater(() -> p.update(plan, status, makeable, xp, lvl, pie, showing));
	}

	private static String ago(long at)
	{
		long s = (System.currentTimeMillis() - at) / 1000;
		if (s < 60)
		{
			return "just now";
		}
		long m = s / 60;
		return m < 60 ? m + " min ago" : (m / 60) + " h ago";
	}

	private static Potion parse(String name)
	{
		try
		{
			return name == null || name.isEmpty() ? null : Potion.valueOf(name);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}
}

package com.potionprep;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.ScriptID;

/**
 * Reads the bank's potion storage the same way the core Bank Tags plugin
 * does: for every storable potion (finished and unfinished), run the game's
 * POTIONSTORE_DOSES script, which returns how many doses are stored.
 *
 * Potion storage is an unlock. Without it every potion reports 0 doses, so
 * the result is simply empty and counts fall back to bank + inventory.
 *
 * Must run on the client thread, outside of another script (e.g. ClientTick).
 */
final class PotionStorageReader
{
	private PotionStorageReader()
	{
	}

	/**
	 * @return item id to units held in storage, keyed by the potion's 1-dose
	 * item id. For finished potions the value is total doses; for unfinished
	 * potions (one "dose" each) it is the number of potions. Both line up
	 * with {@link Node#count}, which weights each id by its dose.
	 */
	static Map<Integer, Integer> read(Client client)
	{
		Map<Integer, Integer> out = new HashMap<>();
		for (int listId : new int[]{EnumID.POTIONSTORE_POTIONS, EnumID.POTIONSTORE_UNFINISHED_POTIONS})
		{
			EnumComposition list = client.getEnum(listId);
			if (list == null)
			{
				continue;
			}
			for (int potionEnumId : list.getIntVals())
			{
				EnumComposition potion = client.getEnum(potionEnumId);
				if (potion == null)
				{
					continue;
				}
				client.runScript(ScriptID.POTIONSTORE_DOSES, potionEnumId);
				int doses = client.getIntStack()[0];
				int oneDoseId = potion.getIntValue(1);
				if (doses > 0 && oneDoseId > 0)
				{
					out.merge(oneDoseId, doses, Integer::sum);
				}
			}
		}
		return out;
	}
}

package com.potionprep;

import java.util.Arrays;
import java.util.List;
import lombok.Getter;
import lombok.Value;

/** One crafting action: inputs (+ optional tool) to {@link #yield} units of a product. */
@Getter
public final class Recipe
{
	@Value
	public static class Input
	{
		Node node;
		int qty;
	}

	private final int level;
	/**
	 * True when the product is just another form of the input (cleaning a
	 * herb, crushing a horn). Shortfalls are then reported on the product,
	 * "short 5 ranarr weed" rather than "short 5 grimy ranarr weed".
	 */
	private final boolean altForm;
	private final int yield;
	private final List<Input> inputs;
	private final Node tool;
	/** Step text; %d is the number of crafts. */
	private final String stepFormat;
	/** Herblore XP per craft. */
	private double xp;

	private Recipe(int level, boolean altForm, int yield, Node tool, String stepFormat, Input... inputs)
	{
		this.level = level;
		this.altForm = altForm;
		this.yield = yield;
		this.tool = tool;
		this.stepFormat = stepFormat;
		this.inputs = Arrays.asList(inputs);
	}

	/** Sets the XP per craft. */
	Recipe xp(double xp)
	{
		this.xp = xp;
		return this;
	}

	static Input in(Node node, int qty)
	{
		return new Input(node, qty);
	}

	static Recipe clean(Node grimy, int level)
	{
		return new Recipe(level, true, 1, null, "Clean %d " + Catalog.lower(grimy.getName()), in(grimy, 1));
	}

	static Recipe crush(Node raw, int yield, Node pestle)
	{
		return new Recipe(1, true, yield, pestle, "Crush %d " + Catalog.lower(raw.getName()), in(raw, 1));
	}

	static Recipe mix(int level, int yield, String stepFormat, Input... inputs)
	{
		return new Recipe(level, false, yield, null, stepFormat, inputs);
	}
}

package com.potionprep;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class GearTest
{
	@Test
	public void onlyBankedUnwornGearInEquipmentShape()
	{
		Map<Integer, Integer> bank = new HashMap<>();
		bank.put(ItemID.MM_ALCHEMIST_HAT, 1);
		bank.put(ItemID.AMULET_OF_CHEMISTRY, 5);
		bank.put(ItemID.MM_ALCHEMIST_GLOVES, 1);
		bank.put(ItemID.SKILLCAPE_HERBLORE, 1);
		// Wearing a trimmed cape: the banked untrimmed one still wins;
		// the labcoat is only a placeholder, so it shows faded.
		List<int[]> rows = Gear.rows(id -> bank.getOrDefault(id, 0) > 0,
			id -> id == ItemID.SKILLCAPE_HERBLORE_TRIMMED || id == ItemID.MM_ALCHEMIST_BODY_ALT);
		assertEquals(4, rows.size());
		assertArrayEquals(new int[]{-1, ItemID.MM_ALCHEMIST_HAT, -1}, rows.get(0));
		assertArrayEquals(new int[]{ItemID.SKILLCAPE_HERBLORE, ItemID.AMULET_OF_CHEMISTRY, -1}, rows.get(1));
		assertArrayEquals(new int[]{-1, ItemID.MM_ALCHEMIST_BODY_ALT, -1}, rows.get(2));
		assertArrayEquals(new int[]{ItemID.MM_ALCHEMIST_GLOVES, -1, -1}, rows.get(3));
	}

	@Test
	public void nothingOwned()
	{
		assertEquals(0, Gear.rows(id -> false, id -> false).size());
	}

	@Test
	public void movesBelowWideRows()
	{
		List<boolean[]> occupied = new ArrayList<>();
		occupied.add(new boolean[]{false, false, false, true, true, true, true, true});
		occupied.add(new boolean[]{true, true, true, true, true, true, true, true});
		List<int[]> gear = new ArrayList<>();
		gear.add(new int[]{-1, 1, -1});
		gear.add(new int[]{-1, 2, -1});
		assertEquals(2, Gear.startRow(occupied, gear));
		occupied.remove(1);
		assertEquals(0, Gear.startRow(occupied, gear));
	}
}

package com.potionprep;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class PotionPlanTest
{
	private static Map<Integer, Integer> counts(int... pairs)
	{
		Map<Integer, Integer> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put(pairs[i], pairs[i + 1]);
		}
		return m;
	}

	private static String steps(PotionPlan plan)
	{
		return plan.getSteps().stream().map(PotionPlan.Step::getText).collect(Collectors.joining(" | "));
	}

	@Test
	public void xpIncludesPrepSteps()
	{
		Map<Integer, Integer> c = new java.util.HashMap<>();
		c.put(ItemID.UNIDENTIFIED_RANARR, 10);
		c.put(ItemID.VIAL_WATER, 10);
		c.put(ItemID.SNAPE_GRASS, 10);
		// 10 x clean (7.5) + 10 x mix (87.5); the unf step gives none.
		assertEquals(950.0, PotionPlan.xp(Potion.PRAYER, c, 99), 0.001);
	}

	@Test
	public void oneRowPerTaskWithInputsButNotOutput()
	{
		List<int[]> rows = PotionPlan.layoutRows(Potion.SUPERANTIPOISON);
		assertEquals(4, rows.size());
		assertArrayEquals(new int[]{ItemID.UNIDENTIFIED_IRIT}, rows.get(0));
		assertArrayEquals(new int[]{ItemID.IRIT_LEAF, ItemID.VIAL_WATER}, rows.get(1));
		assertArrayEquals(new int[]{ItemID.UNICORN_HORN, ItemID.PESTLE_AND_MORTAR}, rows.get(2));
		assertArrayEquals(new int[]{ItemID.IRITVIAL, ItemID.UNICORN_HORN_DUST}, rows.get(3));
	}

	@Test
	public void plainSecondaryHasNoTaskRowOfItsOwn()
	{
		List<int[]> rows = PotionPlan.layoutRows(Potion.PRAYER);
		assertEquals(3, rows.size());
		assertArrayEquals(new int[]{ItemID.RANARRVIAL, ItemID.SNAPE_GRASS}, rows.get(2));
	}

	@Test
	public void staminaTasksChainThroughSuperEnergy()
	{
		List<int[]> rows = PotionPlan.layoutRows(Potion.STAMINA);
		assertEquals(4, rows.size());
		assertArrayEquals(new int[]{ItemID.AVANTOEVIAL, ItemID.MORTMYREMUSHROOM}, rows.get(2));
		assertArrayEquals(new int[]{ItemID._1DOSE2ENERGY, ItemID._2DOSE2ENERGY, ItemID._3DOSE2ENERGY, ItemID._4DOSE2ENERGY,
			ItemID.AMYLASE}, rows.get(3));
		assertFalse(PotionPlan.layoutItems(Potion.STAMINA).contains(ItemID._4DOSESTAMINA));
	}

	@Test
	public void rowsFitTheBankAndSkipTheFinishedPotion()
	{
		for (Potion p : Potion.values())
		{
			for (int[] row : PotionPlan.layoutRows(p))
			{
				assertTrue(p.name(), row.length >= 1 && row.length <= PotionPlan.BANK_COLUMNS);
			}
			for (int id : p.getProduct().rowIds())
			{
				assertFalse(p.name(), PotionPlan.layoutItems(p).contains(id));
			}
		}
	}

	@Test
	public void readyWhenUnfAndSecondaryInHand()
	{
		PotionPlan plan = PotionPlan.compute(Potion.PRAYER, counts(ItemID.RANARRVIAL, 14, ItemID.SNAPE_GRASS, 20), 99);
		assertEquals(14, plan.getMakeable());
		assertEquals(14, plan.getMakeableNow());
		String s = steps(plan);
		assertTrue(s, s.contains("Mix 14 prayer potions"));
		assertTrue(s, s.contains("Short 6 ranarr weed"));
	}

	@Test
	public void cleansAndMixesGrimyHerbs()
	{
		PotionPlan plan = PotionPlan.compute(Potion.PRAYER, counts(ItemID.UNIDENTIFIED_RANARR, 10, ItemID.RANARR_WEED, 4,
			ItemID.VIAL_WATER, 100, ItemID.SNAPE_GRASS, 100), 99);
		assertEquals(14, plan.getMakeable());
		assertEquals(0, plan.getMakeableNow());
		String s = steps(plan);
		assertTrue(s, s.contains("Clean 10 grimy ranarr weed"));
		assertTrue(s, s.contains("Make 14 ranarr (unf)"));
		assertTrue(s, s.contains("Short 86 ranarr weed"));
	}

	@Test
	public void vialsLimit()
	{
		PotionPlan plan = PotionPlan.compute(Potion.PRAYER, counts(ItemID.RANARR_WEED, 20, ItemID.VIAL_WATER, 5, ItemID.SNAPE_GRASS, 20), 99);
		assertEquals(5, plan.getMakeable());
		assertTrue(steps(plan), steps(plan).contains("Short 15 vial of water"));
	}

	@Test
	public void nonCrushableSecondaryNeverGetsACrushStep()
	{
		// The bug in the screenshot: super energy suggested crushing mort myre fungus.
		PotionPlan plan = PotionPlan.compute(Potion.SUPER_ENERGY, counts(ItemID.AVANTOEVIAL, 314, ItemID.MORTMYREMUSHROOM, 957,
			ItemID.AVANTOE, 110, ItemID.VIAL_WATER, 4240, ItemID.UNIDENTIFIED_AVANTOE, 2148), 99);
		assertEquals(957, plan.getMakeable());
		assertEquals(314, plan.getMakeableNow());
		String s = steps(plan);
		assertFalse(s, s.contains("Crush"));
		assertTrue(s, s.contains("Clean 533 grimy avantoe"));
		assertTrue(s, s.contains("Make 643 avantoe (unf)"));
		assertTrue(s, s.contains("Short 1,615 mort myre fungus"));
	}

	@Test
	public void hugeCountsDoNotOverflow()
	{
		PotionPlan plan = PotionPlan.compute(Potion.SUPER_ENERGY, counts(ItemID.AVANTOEVIAL, Integer.MAX_VALUE, ItemID.MORTMYREMUSHROOM, 10), 99);
		assertEquals(10, plan.getMakeable());
	}

	@Test
	public void crushesRawSecondaryOnlyWithPestle()
	{
		Map<Integer, Integer> c = counts(ItemID.LANTADYMEVIAL, 10, ItemID.BLUE_DRAGON_SCALE, 10);
		PotionPlan noPestle = PotionPlan.compute(Potion.ANTIFIRE, c, 99);
		assertEquals(0, noPestle.getMakeable());
		assertTrue(steps(noPestle), steps(noPestle).contains("No pestle and mortar"));

		c.put(ItemID.PESTLE_AND_MORTAR, 1);
		PotionPlan withPestle = PotionPlan.compute(Potion.ANTIFIRE, c, 99);
		assertEquals(10, withPestle.getMakeable());
		assertTrue(steps(withPestle), steps(withPestle).contains("Crush 10 blue dragon scale"));
	}

	@Test
	public void staminaChainsThroughSuperEnergy()
	{
		// 2 super energy(4) = 8 doses on hand, plus 2 unf + 2 fungus = 6 more doses.
		PotionPlan plan = PotionPlan.compute(Potion.STAMINA, counts(ItemID._4DOSE2ENERGY, 2, ItemID.AVANTOEVIAL, 2,
			ItemID.MORTMYREMUSHROOM, 2, ItemID.AMYLASE, 100), 99);
		assertEquals(3, Potion.STAMINA.toPotions(plan.getMakeable()));
		assertEquals("Stamina potion(4)", Potion.STAMINA.potionName());
		assertEquals("Prayer potion(3)", Potion.PRAYER.potionName());
		assertEquals(14, plan.getMakeable());
		assertEquals(8, plan.getMakeableNow());
		String s = steps(plan);
		assertTrue(s, s.contains("Mix 2 super energies"));
		assertTrue(s, s.contains("Add amylase to 14 doses"));
	}

	@Test
	public void superCombatNeedsAllThreeSupers()
	{
		PotionPlan plan = PotionPlan.compute(Potion.SUPER_COMBAT, counts(ItemID._4DOSE2ATTACK, 5, ItemID._4DOSE2STRENGTH, 5,
			ItemID._4DOSE2DEFENSE, 3, ItemID.TORSTOL, 10), 99);
		assertEquals(3, plan.getMakeable());
		assertTrue(steps(plan), steps(plan).contains("Super defence: short 10 cadantine, 10 vial of water, 10 white berries"));
	}

	@Test
	public void levelTooLow()
	{
		PotionPlan plan = PotionPlan.compute(Potion.ZAMORAK_BREW, counts(ItemID.UNIDENTIFIED_TORSTOL, 5, ItemID.VIAL_WATER, 5, ItemID.JANGERBERRIES, 5), 60);
		assertEquals(0, plan.getMakeable());
		assertTrue(steps(plan), steps(plan).contains("Needs 78 Herblore"));
	}

	@Test
	public void potionStorageCountsAddToBank()
	{
		// PotionStorageReader keys storage by the 1-dose id with total doses,
		// and unf potions by their own id. Bank has 1 super energy(4) = 4 doses.
		Map<Integer, Integer> c = counts(ItemID._4DOSE2ENERGY, 1, ItemID.AMYLASE, 100);
		c.merge(ItemID._1DOSE2ENERGY, 37, Integer::sum);   // 37 doses in storage
		PotionPlan plan = PotionPlan.compute(Potion.STAMINA, c, 99);
		assertEquals(41, plan.getMakeable());

		Map<Integer, Integer> unf = counts(ItemID.SNAPE_GRASS, 50);
		unf.merge(ItemID.RANARRVIAL, 12, Integer::sum);       // 12 unf in storage
		assertEquals(12, PotionPlan.compute(Potion.PRAYER, unf, 99).getMakeable());
	}

	@Test
	public void noPotionStorageUnlockFallsBackToBank()
	{
		// Without the unlock the reader returns nothing; bank counts alone apply.
		PotionPlan plan = PotionPlan.compute(Potion.PRAYER, counts(ItemID.RANARRVIAL, 5, ItemID.SNAPE_GRASS, 50), 99);
		assertEquals(5, plan.getMakeable());
	}

	@Test
	public void pieUnlocksPotionsWithinFourLevels()
	{
		// Saradomin brew is level 81.
		assertTrue(PotionPlan.needsPie(Potion.SARADOMIN_BREW, 77, 77));
		assertEquals(81, PotionPlan.effectiveLevel(Potion.SARADOMIN_BREW, 77, 77));
		assertFalse(PotionPlan.needsPie(Potion.SARADOMIN_BREW, 76, 76));   // pie isn't enough
		assertFalse(PotionPlan.needsPie(Potion.SARADOMIN_BREW, 77, 81));   // already boosted
		assertFalse(PotionPlan.needsPie(Potion.SARADOMIN_BREW, 81, 81));   // no boost needed

		Map<Integer, Integer> c = counts(ItemID.TOADFLAXVIAL, 5, ItemID.CRUSHED_BIRD_NEST, 5, ItemID.HALF_BOTANICAL_PIE, 1);
		PotionPlan plan = PotionPlan.compute(Potion.SARADOMIN_BREW, c, PotionPlan.effectiveLevel(Potion.SARADOMIN_BREW, 77, 77), true);
		assertEquals(5, plan.getMakeable());
		assertEquals("Eat a botanical pie (+4)", plan.getSteps().get(0).getText());
		assertEquals(1, plan.getRows().get(0).getHave());

		PotionPlan noPie = PotionPlan.compute(Potion.SARADOMIN_BREW, counts(ItemID.TOADFLAXVIAL, 5, ItemID.CRUSHED_BIRD_NEST, 5), 81, true);
		assertEquals("Need a botanical pie (+4)", noPie.getSteps().get(0).getText());
	}
}

